void dfs(int step) {
    if (step == 1) {
        ans = max(ans, d[0][1]);
        return;
    }
    int old[N][2];
    for (int i = 0; i < step; i++) {
        old[i][0] = d[i][0];
        old[i][1] = d[i][1];
    }
    for (int i = 0; i < step - 1; i++) {
        int a = d[i][0], b = d[i + 1][0];
        int c = d[i][1] + d[i + 1][1] + a * b;
        d[i][0] = a + b;
        d[i][1] = c;
        for (int j = i + 1; j < step - 1; j++) {
            d[j][0] = old[j + 1][0];
            d[j][1] = old[j + 1][1];
        }
        dfs(step - 1);
        for (int j = 0; j < step; j++) {
            d[j][0] = old[j][0];
            d[j][1] = old[j][1];
        }
    }
}

