#include <iostream>
#include <iomanip>
using namespace std;

double f(double x) {
    return x * x * x - x - 1;
}

double solve(double a, double b, double eps) {
    if (f(a) * f(b) > 0) return -1;
    while (b - a > eps) {
        double mid = (a + b) / 2;
        if (f(mid) == 0) return mid;
        if (f(a) * f(mid) < 0) {
            b = mid;
        } else {
            a = mid;
        }
    }
    return (a + b) / 2;
}

int main() {
    double a, b, eps;
    cin >> a >> b >> eps;
    double ans = solve(a, b, eps);
    if (ans == -1) {
        cout << "No guaranteed root" << endl;
    } else {
        cout << fixed << setprecision(6) << ans << endl;
    }
    return 0;
}

