const int N = 100005;
int pre[N], suf[N];
int main() {
    string s, t;
    cin >> s >> t;
    int slen = s.size(), tlen = t.size();
    // pre[i]: t的前i个字符在s中匹配的最左位置
    pre[0] = 0;
    for (int i = 1, p = 0; i <= tlen; i++) {
        while (p < slen && s[p] != t[i - 1]) p++;
        if (p < slen) p++;
        pre[i] = p;
    }
    // suf[i]: t的后i个字符在s中匹配的最右位置
    suf[tlen] = slen + 1;
    for (int i = tlen, p = slen; i >= 1; i--) {
        while (p >= 1 && s[p - 1] != t[i - 1]) p--;
        if (p >= 1) p--;
        suf[i - 1] = p + 1;
    }
    int ans = 0;
    for (int i = 0; i < tlen; i++) {
        int j = i + 1;
        if (pre[i] < suf[i]) {
            ans = max(ans, suf[i] - pre[i] - 1);
        }
    }
    // 考虑删除前缀或后缀
    ans = max(ans, slen - pre[tlen]);
    ans = max(ans, suf[0] - 1);
    cout << ans << endl;
    return 0;
}

