#include <iostream>
using namespace std;
const int N = 100005;
long long sum[N << 2], lazy[N << 2];
int a[N];

void pushup(int rt) {
    sum[rt] = sum[rt << 1] + sum[rt << 1 | 1];
}

void pushdown(int rt, int ln, int rn) {
    if (__1__) {  // 有lazy标记
        lazy[rt << 1] += lazy[rt];
        sum[rt << 1] += lazy[rt] * ln;
        lazy[rt << 1 | 1] += lazy[rt];
        sum[rt << 1 | 1] += lazy[rt] * rn;
        __2__;  // 清除当前lazy
    }
}

void build(int l, int r, int rt) {
    lazy[rt] = 0;
    if (l == r) { sum[rt] = a[l]; return; }
    int mid = (l + r) >> 1;
    build(l, mid, rt << 1);
    build(mid + 1, r, rt << 1 | 1);
    pushup(rt);
}

void update(int L, int R, long long v, int l, int r, int rt) {
    if (L <= l && r <= R) {
        lazy[rt] += v;
        sum[rt] += v * (r - l + 1);
        return;
    }
    int mid = (l + r) >> 1;
    pushdown(rt, mid - l + 1, __3__);
    if (L <= mid) update(L, R, v, l, mid, rt << 1);
    if (R > mid) update(L, R, v, mid + 1, r, rt << 1 | 1);
    __4__;
}

long long query(int L, int R, int l, int r, int rt) {
    if (L <= l && r <= R) return sum[rt];
    int mid = (l + r) >> 1;
    pushdown(rt, mid - l + 1, r - mid);
    long long ans = 0;
    if (L <= mid) ans += query(L, R, l, mid, rt << 1);
    if (R > mid) ans += query(L, R, mid + 1, r, rt << 1 | 1);
    __5__;
}

int main() {
    int n, m; cin >> n >> m;
    for (int i = 1; i <= n; i++) cin >> a[i];
    build(1, n, 1);
    while (m--) {
        int op, l, r; long long v;
        cin >> op >> l >> r;
        if (op == 1) { cin >> v; update(l, r, v, 1, n, 1); }
        else cout << query(l, r, 1, n, 1) << endl;
    }
    return 0;
}

