void getNext(char p[], int nxt[]) {
    int len = strlen(p);
    nxt[0] = -1;
    int k = -1, j = 0;
    while (j < len - 1) {
        if (k == -1 || p[j] == p[k]) {
            j++; k++;
            nxt[j] = k;
        } else {
            k = nxt[k];
        }
    }
}

int kmp(char s[], char p[]) {
    int i = 0, j = 0;
    int slen = strlen(s), plen = strlen(p);
    int cnt = 0;
    while (i < slen) {
        if (j == -1 || s[i] == p[j]) {
            i++; j++;
        } else {
            j = nxt[j];
        }
        if (j == plen) {
            cnt++;
            j = nxt[j - 1];
        }
    }
    return cnt;
}

