    int L = 1, R = 0;
    for (int i = 0; i < m; i++) {
        while (L > q[i].l) add(--L);
        while (R < q[i].r) add(++R);
        while (L < q[i].l) remove(L++);
        while (R > q[i].r) remove(R--);
        ans[q[i].id] = cur;
    }
