#include <iostream>
#include <algorithm>
using namespace std;
const int N = 100005;
int tree[N << 2], a[N];

void build(int l, int r, int rt) {
    if (l == r) {
        tree[rt] = a[l];
        return;
    }
    int mid = (l + r) >> 1;
    build(l, mid, rt << 1);
    build(mid + 1, r, rt << 1 | 1);
    tree[rt] = max(tree[rt << 1], tree[rt << 1 | 1]);
}

void update(int pos, int val, int l, int r, int rt) {
    if (l == r) {
        tree[rt] = val;
        return;
    }
    int mid = (l + r) >> 1;
    if (pos <= mid)
        update(pos, val, l, mid, rt << 1);
    else
        update(pos, val, mid + 1, r, rt << 1 | 1);
    tree[rt] = max(tree[rt << 1], tree[rt << 1 | 1]);
}

int query(int L, int R, int l, int r, int rt) {
    if (L <= l && r <= R) return tree[rt];
    int mid = (l + r) >> 1;
    int ans = -1e9;
    if (L <= mid)
        ans = max(ans, query(L, R, l, mid, rt << 1));
    if (R > mid)
        ans = max(ans, query(L, R, mid + 1, r, rt << 1 | 1));
    return ans;
}

int main() {
    int n, m;
    cin >> n >> m;
    for (int i = 1; i <= n; i++) cin >> a[i];
    build(1, n, 1);
    while (m--) {
        int op, x, y;
        cin >> op >> x >> y;
        if (op == 1) update(x, y, 1, n, 1);
        else cout << query(x, y, 1, n, 1) << endl;
    }
    return 0;
}

#include <iostream>
